sys_variable_value.value:
(function execute(inputs, outputs) {
    try{
        var sysId = inputs.current_value; 
        var rs_ritm = new GlideRecord('sc_req_item');
        rs_ritm.addQuery('sys_id',sysId);
        rs_ritm.query();
        var ritm=null;
        if(rs_ritm.next()){
            ritm=rs_ritm;
        }
        var flow_inputs={};
        flow_inputs['table_name'] = 'sc_req_item';
        flow_inputs['request_item'] = ritm;
        sn_fd.FlowAPI.getRunner().flow('x_1756219_practi_0.practice_3_for_part_3').inForeground().withInputs(flow_inputs).run();
    } catch (ex) {
        var message = ex.getMessage();
        gs.error(message);
    }
})(inputs, outputs);

